"""Explicit labels for generated artifacts; never translate supplied content.

Only literal call sites use this catalog. Historical prose, quotations, data keys,
worksheet names and formulas are not passed through a translation sweep.
"""
from datetime import datetime
from functools import wraps

from bellomberg.core.language import capture_language, language_context


def localized(function):
    """Add a keyword-only language boundary and keep nested renderers consistent."""
    @wraps(function)
    def render(*args, language=None, **kwargs):
        with language_context(capture_language(language)):
            return function(*args, **kwargs)
    return render


def label(key, **values):
    pair = LABELS[key]  # Missing labels are errors, never another language.
    value = pair[0 if capture_language() == "it" else 1]
    return value.format(**values) if values else value


def number(value, spec=",.0f"):
    rendered = format(value, spec)
    return rendered.translate(str.maketrans(",.", ".,")) if capture_language() == "it" else rendered


def date_label(value=None, *, weekday=False):
    value = value or datetime.now()
    language = capture_language()
    months = MONTHS[language]
    prefix = DAYS[language][value.weekday()] + " " if weekday else ""
    return f"{prefix}{value.day} {months[value.month - 1]} {value.year}"


